package com.livingworld.launcher

import android.content.ContentProvider
import android.content.ContentValues
import android.database.Cursor
import android.net.Uri
import android.os.ParcelFileDescriptor
import java.io.File

/**
 * Temporary private destination for the platform MMS download service.
 * This provider exposes no directory listing or unrestricted file access.
 * Tokens are generated by the caller; only UUID-shaped names are accepted.
 */
class MmsDownloadProvider : ContentProvider() {
  override fun onCreate() = true

  override fun openFile(uri: Uri, mode: String): ParcelFileDescriptor {
    require(mode == "w" || mode == "wt" || mode == "r") { "Unsupported MMS file mode" }
    val token = uri.lastPathSegment ?: throw IllegalArgumentException("Missing download token")
    require(uri.pathSegments.size == 2 && uri.pathSegments.first() == "incoming" &&
      TOKEN.matches(token)) { "Invalid MMS download token" }
    val app = context ?: throw IllegalStateException("No content-provider context")
    val directory = File(app.noBackupFilesDir, "mms_pending").apply { mkdirs() }
    val file = File(directory, "$token.pdu")
    val flags = if (mode == "r") ParcelFileDescriptor.MODE_READ_ONLY
      else ParcelFileDescriptor.MODE_CREATE or
        ParcelFileDescriptor.MODE_TRUNCATE or ParcelFileDescriptor.MODE_WRITE_ONLY
    return ParcelFileDescriptor.open(file, flags)
  }

  override fun getType(uri: Uri) = "application/vnd.wap.mms-message"
  override fun query(uri: Uri, projection: Array<out String>?, selection: String?,
    selectionArgs: Array<out String>?, sortOrder: String?): Cursor? = null
  override fun insert(uri: Uri, values: ContentValues?): Uri? = null
  override fun update(uri: Uri, values: ContentValues?, selection: String?,
    selectionArgs: Array<out String>?): Int = 0
  override fun delete(uri: Uri, selection: String?, selectionArgs: Array<out String>?): Int = 0

  companion object {
    private val TOKEN = Regex("[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}")
    fun destination(context: android.content.Context, token: String): Uri =
      Uri.Builder().scheme("content").authority("${context.packageName}.mmsdownloads")
        .appendPath("incoming").appendPath(token).build()
  }
}
